FILE: app/src/label-position.ts
```ts
import type { Camera } from "@babylonjs/lite";
import {
  getViewMatrix,
  getViewProjectionMatrix,
  getEffectiveAspectRatio,
  resolveCameraViewport,
  projectWorldToScreen,
  getCameraPosition,
} from "@babylonjs/lite";

export function labelPosition(
  camera: Camera,
  canvas: HTMLCanvasElement,
  point: { x: number; y: number; z: number }
): { x: number; y: number; visible: boolean } {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;
  const cssWidth = canvas.clientWidth;
  const cssHeight = canvas.clientHeight;

  const aspectRatio = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspectRatio);
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);

  const options: {
    viewport: { x: number; y: number; width: number; height: number };
    backingWidth: number;
    backingHeight: number;
    cssWidth: number;
    cssHeight: number;
    worldOrigin?: { x: number; y: number; z: number };
  } = {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
  };

  if (camera._useFloatingOrigin) {
    options.worldOrigin = getCameraPosition(camera);
  }

  const result = projectWorldToScreen(point, view, viewProjection, options);

  return {
    x: result.cssX,
    y: result.cssY,
    visible: !result.behindCamera && !result.offscreen,
  };
}
```

I wrote `src/label-position.ts` which projects the world point through the camera's view-projection matrix using Babylon Lite's `projectWorldToScreen`, then reads back `cssX`/`cssY` (already in CSS pixels from the canvas top-left) and marks the point visible when it is neither behind the camera nor offscreen — so points beyond the far plane still count as visible, while points outside the frustum's side/top/bottom edges do not. The one thing I'm not fully certain of is whether `projectWorldToScreen`'s `cssX`/`cssY` are measured from the canvas top-left or from the viewport top-left; the notes and the options shape (which include both the full-canvas `backingWidth`/`backingHeight` and the sub-rectangle `viewport`) strongly suggest canvas-relative, but the library isn't here to confirm.
